# CEE 492 Project 3 — NBI Random Forest classification (Good / Fair / Poor)
# Install once at julia>: import Pkg; Pkg.add(["CSV", "DataFrames", "DecisionTree", "Plots"])
# Run at julia>: include("nbi_random_forest.jl")
# Put this file beside the original NBI .txt; keep model_results/bridge_partitions.csv
# generated by the Logistic Regression run to ensure EXACTLY the same bridge split.

module NBIRandomForest
using CSV, DataFrames, Statistics, Random, DecisionTree, Plots

const CLASSES = ["Good", "Fair", "Poor"]
const NUMERIC_FEATURES = ["age", "adt", "truck_share", "spans", "length", "max_span", "deck_width", "deck_area", "year"]
const CATEGORICAL_FEATURES = ["owner", "material", "design"]
const LOG_FEATURES = Set(["adt", "length", "max_span", "deck_area"])

function numeric_value(v, name::String)
    ismissing(v) && return NaN
    x = Float64(v)
    if !isfinite(x) || (name == "spans" && x <= 0) ||
       (name in ("length", "max_span", "deck_area", "deck_width") && x <= 0) ||
       (name in ("age", "adt", "truck_share") && x < 0)
        return NaN
    end
    return name in LOG_FEATURES ? log1p(x) : x
end

function categorical_value(v)
    ismissing(v) && return "Unknown"
    s = strip(String(v))
    return isempty(s) ? "Unknown" : s
end

# Match the Logistic Regression's fitted preprocessing, including feature order.
function fit_preprocessor(df)
    stats = Dict{String,Tuple{Float64,Float64,Float64}}()
    for name in NUMERIC_FEATURES
        vals = [numeric_value(v, name) for v in df[!, name]]
        observed = filter(isfinite, vals)
        med = isempty(observed) ? 0.0 : median(observed)
        replaced = [isfinite(v) ? v : med for v in vals]
        mu, sigma = mean(replaced), std(replaced)
        stats[name] = (med, mu, sigma > 0 ? sigma : 1.0)
    end
    levels = Dict{String,Vector{String}}()
    for name in CATEGORICAL_FEATURES
        levels[name] = sort!(unique(vcat([categorical_value(v) for v in df[!, name]], ["Unknown"])))
    end
    return (stats=stats, levels=levels)
end

function transform(df, prep)
    result = DataFrame()
    for name in NUMERIC_FEATURES
        vals = [numeric_value(v, name) for v in df[!, name]]
        med, mu, sigma = prep.stats[name]
        result[!, Symbol(name)] = Float32[((isfinite(v) ? v : med) - mu) / sigma for v in vals]
        result[!, Symbol(name * "_missing")] = Float32[!isfinite(v) for v in vals]
    end
    result[!, :deck_width_zero] = Float32[!ismissing(v) && v == 0 for v in df.deck_width]
    result[!, :adt_zero] = Float32[!ismissing(v) && v == 0 for v in df.adt]
    for name in CATEGORICAL_FEATURES
        vals = [categorical_value(v) for v in df[!, name]]
        known = Set(prep.levels[name])
        vals = [v in known ? v : "Unknown" for v in vals]
        for (i, level) in enumerate(prep.levels[name][2:end])
            result[!, Symbol(name * "_" * string(i))] = Float32[v == level for v in vals]
        end
    end
    return Matrix{Float32}(result)
end

function evaluate(ytrue::Vector{String}, ypred::Vector{String})
    @assert length(ytrue) == length(ypred)
    cm = zeros(Int, 3, 3)
    idx = Dict(c => i for (i, c) in enumerate(CLASSES))
    for (t, p) in zip(ytrue, ypred)
        cm[idx[t], idx[p]] += 1
    end
    precision = Float64[]; recall = Float64[]; f1 = Float64[]
    for i in 1:3
        tp = cm[i,i]
        pr = tp / max(sum(cm[:,i]), 1)
        re = tp / max(sum(cm[i,:]), 1)
        push!(precision, pr)
        push!(recall, re)
        push!(f1, pr + re > 0 ? 2 * pr * re / (pr + re) : 0.0)
    end
    scores = (accuracy=sum(cm[i,i] for i in 1:3) / sum(cm),
              macro_f1=mean(f1), balanced_accuracy=mean(recall),
              poor_recall=recall[3], poor_precision=precision[3])
    per_class = DataFrame(class=CLASSES, precision=precision, recall=recall,
                          f1=f1, support=vec(sum(cm, dims=2)))
    return scores, per_class, cm
end

function run()
    root = @__DIR__
    data_file = joinpath(root, "Selected_Bridges_September_24_2026_03_51_03.txt")
    split_file = joinpath(root, "model_results", "bridge_partitions.csv")
    outdir = joinpath(root, "rf_results")
    @assert isfile(data_file) "NBI source .txt not found beside nbi_random_forest.jl: $data_file"
    @assert isfile(split_file) "Missing model_results/bridge_partitions.csv; run the existing Logistic Regression script first."
    mkpath(outdir)

    println("STEP 1/5: Reading NBI data ...")
    raw = CSV.read(data_file, DataFrame; quotechar='\'',
        types=Dict("8 - Structure Number" => String, "2025 NBI Structure Number" => String),
        missingstring=["", "NA", "N/A"])
    d = raw[(raw[!, "Year"] .>= 2002) .& (raw[!, "Year"] .<= 2025), :]
    rename!(d, Dict(
        "Year" => "year", "2025 NBI Structure Number" => "bridge_id",
        "22 - Owner Agency" => "owner", "29 - Average Daily Traffic" => "adt",
        "43A - Main Span Material" => "material", "43B - Main Span Design" => "design",
        "45 - Number of Spans in Main Unit" => "spans",
        "49 - Structure Length (ft.)" => "length", "CAT10 - Bridge Condition" => "condition",
        "Bridge Age (yr)" => "age", "CAT29 - Deck Area (sq. ft.)" => "deck_area",
        "48 - Length of Maximum Span (ft.)" => "max_span",
        "109 - Average Daily Truck Traffic (Percent ADT)" => "truck_share",
        "52 - Deck Width - Out to Out (ft.)" => "deck_width"))
    filter!(r -> !ismissing(r.condition) && String(r.condition) in CLASSES, d)
    @assert all(.!ismissing.(d.bridge_id)) "Missing bridge_id prevents grouped split."

    println("STEP 2/5: Loading the SAME bridge partitions used by Logistic Regression ...")
    split = CSV.read(split_file, DataFrame; types=Dict(:bridge_id => String))
    @assert nrow(split) == length(unique(split.bridge_id)) "Duplicate bridge IDs in partition manifest."
    mapping = Dict(String(r.bridge_id) => String(r.partition) for r in eachrow(split))
    @assert all(haskey(mapping, String(id)) for id in d.bridge_id) "Some bridge IDs are absent in the partition manifest."
    @assert Set(values(mapping)) == Set(["train", "validation", "test"]) "Unexpected partition labels."
    d[!, :partition] = [mapping[String(id)] for id in d.bridge_id]
    train = d[d.partition .== "train", :]
    valid = d[d.partition .== "validation", :]
    test = d[d.partition .== "test", :]
    @assert isempty(intersect(Set(train.bridge_id), Set(valid.bridge_id)))
    @assert isempty(intersect(Set(train.bridge_id), Set(test.bridge_id)))
    @assert isempty(intersect(Set(valid.bridge_id), Set(test.bridge_id)))
    println("Training: $(nrow(train)); Validation: $(nrow(valid)); Test: $(nrow(test))")
    CSV.write(joinpath(outdir, "data_split_summary.csv"), DataFrame(
        dataset=["train", "validation", "test"],
        bridges=[length(unique(train.bridge_id)), length(unique(valid.bridge_id)), length(unique(test.bridge_id))],
        observations=[nrow(train), nrow(valid), nrow(test)]))

    println("STEP 3/5: Fitting preprocessing on TRAINING ONLY ...")
    prep = fit_preprocessor(train)
    Xtrain, Xvalid, Xtest = transform(train, prep), transform(valid, prep), transform(test, prep)
    ytrain, yvalid, ytest = String.(train.condition), String.(valid.condition), String.(test.condition)
    println("Number of encoded features: $(size(Xtrain, 2))")

    # Three interpretable settings, with increasing model size.
    # Keep a modest forest size because the dataset has > 580,000 annual observations.
    configs = [(n_trees=30, max_depth=12, min_samples_leaf=20),
               (n_trees=60, max_depth=16, min_samples_leaf=10),
               (n_trees=100, max_depth=20, min_samples_leaf=5)]
    results = DataFrame(n_trees=Int[], max_depth=Int[], min_samples_leaf=Int[],
                        accuracy=Float64[], macro_f1=Float64[], balanced_accuracy=Float64[],
                        poor_recall=Float64[], poor_precision=Float64[])
    best_model = nothing
    best_score = -Inf
    best_config = nothing
    println("STEP 4/5: Training random forests and comparing VALIDATION macro-F1 ...")
    for (i, cfg) in enumerate(configs)
        println("  [$i/$(length(configs))] n_trees=$(cfg.n_trees), depth=$(cfg.max_depth), leaf=$(cfg.min_samples_leaf)")
        model = DecisionTree.build_forest(ytrain, Xtrain,
            -1, cfg.n_trees, 0.7, cfg.max_depth,
            cfg.min_samples_leaf, 2, 0.0; rng=492 + i)
        pred = String.(DecisionTree.apply_forest(model, Xvalid))
        scores, _, _ = evaluate(yvalid, pred)
        push!(results, (cfg.n_trees, cfg.max_depth, cfg.min_samples_leaf,
            scores.accuracy, scores.macro_f1, scores.balanced_accuracy,
            scores.poor_recall, scores.poor_precision))
        println("    validation macro-F1=$(round(scores.macro_f1, digits=4)), Poor recall=$(round(scores.poor_recall, digits=4))")
        if scores.macro_f1 > best_score
            best_score = scores.macro_f1
            best_model = model
            best_config = cfg
        end
    end
    CSV.write(joinpath(outdir, "rf_validation_comparison.csv"), results)
    println("Selected: $best_config (validation macro-F1=$(round(best_score, digits=4)))")

    # Test is used ONCE, after model selection on validation.
    println("STEP 5/5: Evaluating the chosen forest on held-out TEST ...")
    predicted = String.(DecisionTree.apply_forest(best_model, Xtest))
    scores, per_class, cm = evaluate(ytest, predicted)
    println("\nFINAL RANDOM FOREST TEST RESULTS")
    for (k, v) in pairs(scores)
        println("  $k: $(round(v, digits=4))")
    end
    println(per_class)
    CSV.write(joinpath(outdir, "rf_test_per_class_scores.csv"), per_class)
    CSV.write(joinpath(outdir, "rf_test_predictions.csv"),
        DataFrame(bridge_id=test.bridge_id, year=test.year, actual=ytest, predicted=predicted))
    CSV.write(joinpath(outdir, "rf_confusion_matrix.csv"),
        DataFrame(actual=CLASSES, predicted_Good=cm[:,1], predicted_Fair=cm[:,2], predicted_Poor=cm[:,3]))
    CSV.write(joinpath(outdir, "rf_test_summary.csv"), DataFrame(
        n_trees=[best_config.n_trees], max_depth=[best_config.max_depth],
        min_samples_leaf=[best_config.min_samples_leaf],
        accuracy=[scores.accuracy], macro_f1=[scores.macro_f1],
        balanced_accuracy=[scores.balanced_accuracy], poor_recall=[scores.poor_recall],
        poor_precision=[scores.poor_precision]))

    p = heatmap(CLASSES, CLASSES, cm; xlabel="Predicted condition", ylabel="Actual condition",
        title="Random Forest: Test confusion matrix", color=:blues, size=(700,550))
    for i in 1:3, j in 1:3
        annotate!(p, j, i, Plots.text(string(cm[i,j]), 10, :black))
    end
    savefig(p, joinpath(outdir, "rf_confusion_matrix.png"))
    p2 = bar(per_class.class, per_class.f1; xlabel="Condition class", ylabel="F1 score",
        ylims=(0,1), title="Random Forest: Test F1 by class", legend=false, size=(700,450))
    savefig(p2, joinpath(outdir, "rf_per_class_f1.png"))
    p3 = plot(string.(results.n_trees), results.macro_f1; marker=:circle,
        xlabel="Number of trees (with depth/leaf also varied)", ylabel="Validation Macro-F1",
        title="Random Forest: Configuration comparison", legend=false, size=(700,450))
    savefig(p3, joinpath(outdir, "rf_validation_macro_f1.png"))
    println("\nSaved outputs under: $outdir")
    println("NOTE: Compare against the Logistic Regression test values: Accuracy 0.7053, Macro-F1 0.4604, Poor Recall 0.0")
    return nothing
end

end # module NBIRandomForest

NBIRandomForest.run()
